#!/usr/bin/env python3
"""Freeze expanded/review sample parts; never launch or accept review."""
import sys
sys.dont_write_bytecode=True
import pathlib,importlib.util,json,math
P=pathlib.Path(__file__).resolve().parent
sp=importlib.util.spec_from_file_location('w',P/'step-03-wave3-check.py');w=importlib.util.module_from_spec(sp);sp.loader.exec_module(w)
m=w.m;PIN=w.PIN

def save(name,o):(P/name).write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n')
def row(r,strata):
 b=(json.dumps(r,ensure_ascii=False,separators=(',',':'))+'\n').encode();raw=m.blob(PIN,r['file'])
 return {'file':r['file'],'set':r['reviewSet'],'strata':strata,'edges':m.edge_count(r),'recordSha256':m.sha(b),'sourceDigest':r['digest'],'diffSha256':m.sha(r['diff']),'recordBytes':len(b),'sourceBytes':len(raw),'contextPlusRecordBytes':len(b)+len(raw)}
def parts(rows,prefix):
 groups=[];current=[]
 for r in rows:
  if current and (len(current)>=6 or sum(x['edges'] for x in current)+r['edges']>150 or sum(x['contextPlusRecordBytes'] for x in current)+r['contextPlusRecordBytes']>400000):groups.append(current);current=[]
  current.append(r)
 if current:groups.append(current)
 result=[]
 for i,g in enumerate(groups,1):
  report=f'{prefix}{i:02}.md';assert not (P/report).exists(),report
  result.append({'part':i,'report':str(m.REL/report),'files':g,'fileCount':len(g),'edges':sum(x['edges'] for x in g),'sourcePlusRecordBytes':sum(x['contextPlusRecordBytes'] for x in g),'readingPages':[{'file':x['file'],'edgeRanges':[{'first':n+1,'last':min(n+100,x['edges'])} for n in range(0,x['edges'],100)],'maxFieldPageBytes':300000,'method':'Stream source in consecutive ≤120-line chunks and one edge/proof field at a time; a field longer than 300000 bytes is paged as text slices. One complete per-file verdict and diff remain indivisible.'} for x in g],'indivisibleOversize':any(x['edges']>150 or x['contextPlusRecordBytes']>400000 for x in g)})
 return result

def request(name,index,title):
 lines=[f'# {title}','',f'Author pin `{PIN}`. Patch RECORDS only: no consumer edit, no authority flip, no Step 3 self-acceptance. Read A51, L12-10 and L12-21..L12-37 in owner-answers.md, the latest authoring rules digest in progress.md, and the schema in step-03-authoring-request.md. Reviewers started/accepted **0/0**.','',f'Frozen packet: **{index["selectedFiles"]} whole files / {index["selectedEdges"]} coverage edges / {len(index["parts"])} parts**. Index `{name.replace("request.md","index.json")}` binds exact current records, source/diff hashes and per-set membership. Every assigned file must be read whole; hash equality is a binding, never semantic acceptance.','', '## Reading method and scope','', '**Reviewers never run checker or probes.** Read complete pinned consumers with `git show <pin>:<file>` in consecutive bounded chunks; independently read exact committed targets and adjacent descriptions. Use Python field extraction below, never cat/grep/print an entire JSONL line. Review every edge, including preserve, parked, row-flip, author-added and legacy-scan exclusions. Check source-derived unit boundaries, exact carriage declarations, truthful history facts/notes, locators, complete label/destination and relative coordinates.','', 'Related includes body `## Related` lists. Missing-path alias preserves outside declared carriage/history fail L12-37 even in quotations. Undated live decision citations are navigation. Live objects naming a retiring tree require a complete description rewrite. Historical Superseded-by framing stays literal with a record-only note; CoordinationSession history notes must point to h-aabefc85f0c9.md. A same-line or wrapped-list unit defaults to one disposition; independently verify any source-bound Distinct claim exception.','', 'Shipped `docs/contracts/fgos-gateway-api-v1.yaml` remains CTR010/A45: schema/identity/numbering must not change. Generator-owned docs/decisions/index.md parks to `fgos decision-index` via src/report/decision-index.mjs; never hand-patch the projection. Distillery upstream sources are retained with their own external coordinates, distinct from live fgOS claims. Dated explanations/journals preserve historical actions; live navigation in them still follows current rulings. Maintained architect files retire only after reader cutover, with no payload evidence exemption.','', '## Python per-field extractor','', 'Set consumer and batch from the assigned table. Run once per file, reading every printed field; stream long passages/lists as bounded slices. Each page is ≤300,000 bytes (use UTF-8 bytes for byte-sized pages), never a complete serialized record.','', '```python', 'import json, pathlib', "root = pathlib.Path('plans/260925-documentation-authority-unification/reports/phase-08')", "batch = 'COPY BATCH NUMBER'", "consumer = 'COPY EXACT ASSIGNED PATH'", "record = next(json.loads(line) for line in (root/'step-03-records'/f'batch-{batch}.jsonl').read_text().splitlines() if json.loads(line)['file'] == consumer)", 'def emit(label, value):', '    data = json.dumps(value, ensure_ascii=False, indent=2).encode()', '    for start in range(0, len(data), 300000):', "        print(label, 'byte page', start, data[start:start+300000].decode('utf-8', errors='backslashreplace'))", "for key in ('file','authorInputCommit','digest','inventoryEdgeIds','authoringRules','retiresWithTree','edgeIds','reason','diff'):", '    emit(key, record.get(key))', "for edge in record.get('edges', []):", '    for key, value in edge.items(): emit(edge["edgeId"]+" "+key, value)', "for section in ('coverage','anchors','relativeResolution','labelForm'):", "    for key, value in record.get('checks', {}).get(section, {}).items():", "        if key == 'legacyScan':", "            for k, v in value.items():", "                if k != 'candidates': emit(section+' '+key+' '+k, v)", "            for i, candidate in enumerate(value['candidates']): emit('scan candidate '+str(i), candidate)", "        else: emit(section+' '+key, value)", '```','', 'Read source chunks with `git show <pin>:<consumer> | sed -n \'1,120p\'`, then 121–240 and so on through EOF. Large artifacts are streamed with one whole-file verdict: see per-part readingPages in the index. Each ordinary part has ≤6 files, ≤150 edges and ≤400,000 source-plus-record bytes. An indivisible larger file is isolated, its edges read in ≤100-edge pages; no artificial file split or duplicate sample membership.','', '## Set and stratum accounting','']
 if 'perSet' in index:
  lines+=['| Set | Patched population / sample | Mandatory | Patched+mandatory distinct | Unpatched eligible / sample | Union |','|---|---:|---:|---:|---:|---:|']
  for a in index['perSet']:lines.append(f"| {a['set']} | {a['patchedPopulation']}/{a['patchedSeedSample']} | {a['mandatoryFiles']} | {a['patchedAndMandatoryDistinct']} | {a['unpatchedEligiblePopulation']}/{a['unpatchedSample']} | {a['distinctSelected']} |")
  lines+=['','Zero-edge files remain in the freeze; retired consumers are not sampled. Both seeded strata preserve their own per-set population/ranks/ceil(15%) rule, mandatory union and ≤3% rework threshold. A breach expands to every surviving file of that set. Denominators are selected files now, reviewed denominator 0 and rework pending until independent review; never pool or replace a failed sample.']
 else:
  lines+=['L12-37 upholds wave-2 rework 04520 (batch-037 patched sample 1/1) and 06509 (batch-038 unpatched sample 1/1); each breaches 3%. This expansion covers EVERY file of both sets, both strata and zero-edge records, plus every other Part A outcome-changed file (036 and 041). Earlier sample membership is preserved as history, not silently reseeded. Text-only corrections outside expansion do not trigger review; the exact delta is step-03-wave2-r2-changes.json.','', '| Set | Expansion/targeted files | Reviewed denominator | Rework numerator |','|---|---:|---:|---|']
  for a in index['coverageBySet']:lines.append(f"| {a['set']} | {a['files']} | 0 | pending |")
 lines+=['','## Assigned parts','']
 for part in index['parts']:
  lines += [f"### Part {part['part']:02} → `{pathlib.Path(part['report']).name}`",'',f"{part['fileCount']} whole files / {part['edges']} edges / {part['sourcePlusRecordBytes']:,} source-plus-record bytes."+(' **Indivisible file: stream bounded field/edge pages; one verdict.**' if part['indivisibleOversize'] else ''),'','| Set | Consumer | Stratum / reason | Edges |','|---|---|---|---:|']
  for x in part['files']:lines.append(f"| {x['set']} | `{x['file']}` | {', '.join(x['strata'])} | {x['edges']} |")
  lines.append('')
 lines+=['## Required handback','','Write only the assigned unique review report. State pin, complete reading method and record/diff hashes; give a per-file verdict and edges read. Separate outcome defects (rework) from record-text notes and Lead-ruling questions. Report reviewed-file denominator/rework numerator per set AND stratum (including overlaps), not a pooled rate. Keep exact source/target evidence and dissent. No repairs, checker/probes, review dispatch or acceptance.','','Lead owns independent dispatch/acceptance, actual runner-commit accounting in both untouched Phase 6 reproduction manifests, committed-byte acceptance and preview. Workflow/RUL10/GAP-02 carry and Step 5 parity remain outstanding; Phase 8 close and Phase 9 authorization are not claimed. New Lead-ruling gaps required for this author packet: 0. Names use the exact brief-authorized namespace because this worker must not call fgOS CLI.']
 (P/name).write_text('\n'.join(lines)+'\n')

def main():
 m.SETS=w.EARLIER;prior=m.records();save('step-03-wave2-r2-binding-manifest.json',w.binding(prior));delta=json.loads((P/'step-03-wave2-r2-changes.json').read_text());wanted=set(delta['outcomeChangedFiles'])|{r['file'] for r in prior if r['reviewSet'] in ('batch-037','batch-038')};rows=[row(r,['full-set-expansion'] if r['reviewSet'] in ('batch-037','batch-038') else ['Part-A-outcome-change']) for r in prior if r['file'] in wanted];assert len(rows)==len(wanted)
 index={'pin':PIN,'selectedFiles':len(rows),'selectedEdges':sum(x['edges'] for x in rows),'parts':parts(rows,'review-a38-step-03-wave2-x-p'),'coverageBySet':[{'set':b,'files':sum(x['set']==b for x in rows),'reviewedFileDenominator':0,'reworkNumerator':'pending'} for b in sorted({x['set'] for x in rows})],'reviewersStarted':0,'accepted':0,'binding':'step-03-wave2-r2-binding-manifest.json','historicalSample':'step-03-wave2-manifest.json'}
 save('step-03-wave2-expansion-review-index.json',index);request('step-03-wave2-expansion-review-request.md',index,'Step 3 wave 2 — full expansion and Part A outcome re-review')
 m.SETS=w.WAVE3;rs=m.records();frozen=w.freeze(rs);save('step-03-wave3-manifest.json',frozen);by={r['file']:r for r in rs};rows=[];account=[]
 for g in frozen['sets']:
  batch=g['set'];u=frozen['unpatchedStrata'][batch.removeprefix('batch-')];selected=sorted(set(g['selected']+u['selected']))
  account.append({'set':batch,'allFiles':sum(r['reviewSet']==batch for r in rs),'retiringFiles':sum(r['reviewSet']==batch and bool(r.get('retiresWithTree')) for r in rs),'patchedPopulation':g['populationCount'],'patchedSeedSample':len(g['sample']),'mandatoryFiles':len(g['mandatoryWitnesses']),'patchedAndMandatoryDistinct':len(g['selected']),'unpatchedEligiblePopulation':u['populationCount'],'unpatchedSample':len(u['selected']),'distinctSelected':len(selected),'reviewedFileDenominator':0,'reworkNumerator':'pending','patchedStratum':{'selectedDenominator':len(g['selected']),'reviewedDenominator':0,'reworkNumerator':'pending'},'unpatchedStratum':{'selectedDenominator':len(u['selected']),'reviewedDenominator':0,'reworkNumerator':'pending'}})
  for file in selected:
   strata=[]
   if file in g['sample']:strata.append('patched-seeded')
   if file in [x['file'] for x in g['mandatoryWitnesses']]:strata.append('mandatory-threshold')
   if file in u['selected']:strata.append('unpatched-seeded')
   rows.append(row(by[file],strata))
 index={'pin':PIN,'manifest':'step-03-wave3-manifest.json','selectedFiles':len(rows),'selectedEdges':sum(x['edges'] for x in rows),'perSet':account,'parts':parts(rows,'review-a38-step-03-wave3-p'),'reviewersStarted':0,'accepted':0,'semanticAcceptance':'Pending independent Lead acceptance; author freezes bindings only.'};save('step-03-wave3-review-index.json',index);request('step-03-wave3-review-request.md',index,'Step 3 wave 3 — independent A51 per-set review')
 print(json.dumps({'expansionFiles':len(wanted),'expansionParts':len(json.loads((P/'step-03-wave2-expansion-review-index.json').read_text())['parts']),'wave3SelectedFiles':len(rows),'wave3Parts':len(index['parts'])}))
if __name__=='__main__':main()
